	public Effect GetEffect(string effectName)
	{
		string text = effectName.Replace(" ", "").Replace("Effect", "").ToLower();
		for (int i = 0; i < effectsList.Count; i++)
		{
			if (text == effectsList[i].name.Replace("Effect", "").ToLower())
			{
				return effectsList[i];
			}
		}
		return null;
	}
